下列C語言程式可輸出布林代數式F(A, B)之真值表，則F(A, B)為何？
1 #include <stdio.h>
2 int main(void){
3 int X=0, Y=0, Z;
4 printf("%c %c %c\n", 'A', 'B', 'F');
5 do{
6 while(Y<=1){
7 Z=((X||!Y)&&(Y||X));
8 printf("%d %d %d\n", X, Y, Z);
9 Y++;
10 }
11 Y=0;
12 X++;
13 }while(X<=1);
14 return 0;}

曉明寫了下列C語言程式，用來逐字比對字串str中是否有字串query指定的字串，則
程式執行後變數len、ans 和match_count 的值分別為何？
1 #include <stdio.h>
2 int main(){
3 char str[100] = "This is a book and that is a dog.\0";
4 char ans = 0, match_count=0;
5 char query[]="is";//{'i', 's', '\0'};
6 int len = sizeof(query), i , j;
7 printf("len=%d\n", len);
8 //開始逐字比對
9 for(i=0; (i<100-len)&&(str[i]!='\0'); i++){
10 for(j=0; j<len-1; j++)
11 if(query[j]==str[i+j])
12 ans++;
13 else
14 break;
15 if(ans==len-1) //比對到一次就累計match_count
16 printf("%d-th match str[%d] !\n", ++match_count, i);
17 ans=0;
18 }
19 printf("%d, %d, %d", len, ans, match_count);
20 return 0;
21 }

